package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.TravelRequest; import EmployeeManagementSystem.repository.TravelRequestRepository;
import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*;
@Service public class TravelRequestServiceImpl implements TravelRequestService{
 private final TravelRequestRepository repo; public TravelRequestServiceImpl(TravelRequestRepository r){repo=r;}
 public List<TravelRequest> my(String u){return repo.findByUserIdOrderByStartDateDesc(u);} public List<TravelRequest> all(){return repo.findAllByOrderByStartDateDesc();}
 public TravelRequest create(TravelRequest x,String u,String n){validate(x);x.setId(null);x.setUserId(u);x.setEmployeeName(n);x.setStatus("PENDING");return repo.save(x);}
 public TravelRequest update(Long id,TravelRequest x,String u){TravelRequest e=get(id);if(!e.getUserId().equals(u)||!("PENDING".equals(e.getStatus())||"REJECTED".equals(e.getStatus())))throw new IllegalArgumentException("Only your pending or rejected travel requests can be edited.");validate(x);e.setPurpose(x.getPurpose());e.setDestination(x.getDestination());e.setStartDate(x.getStartDate());e.setEndDate(x.getEndDate());e.setTravelMode(x.getTravelMode());e.setItinerary(x.getItinerary());e.setEstimatedCost(x.getEstimatedCost());e.setAdvanceAmount(x.getAdvanceAmount());e.setProjectName(x.getProjectName());e.setStatus("PENDING");return repo.save(e);}
 private void validate(TravelRequest x){if(x.getStartDate()==null||x.getEndDate()==null||x.getEndDate().isBefore(x.getStartDate()))throw new IllegalArgumentException("End date must be on or after start date.");if(x.getEstimatedCost()!=null&&x.getEstimatedCost()<0)throw new IllegalArgumentException("Estimated cost cannot be negative.");if(x.getAdvanceAmount()!=null&&x.getAdvanceAmount()<0)throw new IllegalArgumentException("Advance cannot be negative.");}
 public TravelRequest review(Long id,String s,String c,String r){if(!Set.of("APPROVED","REJECTED","CANCELLED","COMPLETED").contains(s))throw new IllegalArgumentException("Invalid travel status.");TravelRequest e=get(id);if("COMPLETED".equals(s)&&!"APPROVED".equals(e.getStatus()))throw new IllegalArgumentException("Only approved trips can be completed.");if(!"PENDING".equals(e.getStatus())&&!("APPROVED".equals(e.getStatus())&&"COMPLETED".equals(s)))throw new IllegalArgumentException("Request is not in a reviewable state.");e.setStatus(s);e.setManagerComment(c);e.setReviewedBy(r);e.setReviewedAt(LocalDateTime.now());return repo.save(e);}
 public void delete(Long id,String u){TravelRequest e=get(id);if(!e.getUserId().equals(u)||!"PENDING".equals(e.getStatus()))throw new IllegalArgumentException("Only your pending requests can be deleted.");repo.delete(e);} public TravelRequest get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Travel request not found."));}
}
